static constexpr unsigned kGlyphCount=sizeof(kGlyphs)/sizeof(kGlyphs[0]);
static inline const Glyph *find(uint16_t key) {
    size_t left=0,right=kGlyphCount;
    while(left<right) {
        const size_t mid=left+(right-left)/2;
        if(kGlyphs[mid].key<key) left=mid+1; else right=mid;
    }
    return left<kGlyphCount && kGlyphs[left].key==key? &kGlyphs[left] : nullptr;
}
static inline uint16_t next(const uint8_t *s,int len,int *index) {
    if(!s||!index||*index>=len||s[*index]==0) return 0;
    const uint8_t a=s[(*index)++];
    if(a<0x80) return a;
    if(a>=0x81 && a<=0xfe && *index<len) {
        const uint8_t b=s[*index];
        if((b>=0x41 && b<=0x5a)||(b>=0x61 && b<=0x7a)||(b>=0x81 && b<=0xfe)) {
            ++*index; return (uint16_t)(((uint16_t)a<<8)|b);
        }
    }
    return '?';
}
static inline int bounded_length(const uint8_t *s,int length) {
    if(!s) return 0;
    if(length>=0) return length>1024?1024:length;
    if(length!=-1) return 0;
    int n=0; while(n<1024 && s[n]) ++n;
    return n;
}
static inline int measure(const uint8_t *s,int len) {
    int n=bounded_length(s,len), i=0,w=0, widest=0;
    while(i<n) {
        const uint16_t key=next(s,n,&i);
        if(!key) break;
        if(key=='\n') { if(w>widest) widest=w; w=0; continue; }
        const Glyph *g=find(key);
        if(!g) g=find('?');
        w+=g?g->advance:7;
    }
    return w>widest?w:widest;
}
